#!/usr/bin/env bash
# The React Native package on Android: clients/react-native/rust/vtxos-uniffi built for the
# two 64-bit ABIs, its bindings and Turbo Module generated by uniffi-bindgen-react-native,
# the TypeScript checked, and the example app built against them.
#
# Needs the Android SDK (ANDROID_HOME) with its command-line tools, a JDK 17 or later, and Node
# with corepack.

. "$(dirname "${BASH_SOURCE[0]}")/lib.sh"
cd "$REPO"

# React Native 0.86's NDK, which the example app builds its C++ with too.
NDK_VERSION=27.1.12297006
CARGO_NDK_VERSION=4.1.2
export ANDROID_NDK_HOME="$ANDROID_HOME/ndk/$NDK_VERSION"

say "android: toolchain"
rustup target add aarch64-linux-android x86_64-linux-android
cargo install cargo-ndk --version "$CARGO_NDK_VERSION" --locked
if [ ! -d "$ANDROID_NDK_HOME" ]; then
    # `yes` is cut off when sdkmanager has read enough, and under pipefail that would fail the
    # script after a good install: only sdkmanager's own result counts.
    (yes 2>/dev/null || true) \
        | "$ANDROID_HOME/cmdline-tools/latest/bin/sdkmanager" --install "ndk;$NDK_VERSION" >/dev/null
fi

cd "$REPO/clients/react-native"
corepack enable
yarn install --immutable

say "android: the library, its bindings and Turbo Module"
yarn ubrn:android

say "android: TypeScript"
yarn typecheck

say "android: the example app"
(cd example/android && ./gradlew --no-daemon --console=plain assembleDebug)
